use vstd::prelude::*;

verus! {

/// Swap the first and last elements of a non‐empty Vec<i32> in place.
/// 
/// Requires:
///   - `a.len() >= 1`
/// Ensures:
///   - length is preserved
///   - the new first element is the old last element
///   - the new last element is the old first element
///   - all interior elements (if any) are unchanged
fn swap_first_and_last(a: &mut Vec<i32>)
    requires
        a.len() >= 1,
    ensures
        // Length is unchanged
        a.len() == old(a@).len(),
        // First element is replaced by the old last
        a@[0] == old(a@)[old(a@).len() - 1],
        // Last element is replaced by the old first
        a@[old(a@).len() - 1] == old(a@)[0],
        // All elements strictly between remain the same
        forall |i: nat|
            1 <= i && i < old(a@).len() - 1
            ==> a@[i] == old(a@)[i],
{
    let n = a.len();
    // Vec::swap has the spec:
    //   requires i < a@.len() && j < a@.len()
    //   ensures  a@ == old(a@).update(i, old(a@)[j]).update(j, old(a@)[i])
    // which exactly gives us the desired post‐conditions.
    a.swap(0, n - 1);
}

}  
